      "met2_ov_tools": "🧪 Four explorers in this module",
      "met2_ph_ac": "Austenite + cementite (γ + Fe₃C)",
      "met2_ph_aus": "Austenite (γ)",
      "met2_ph_delta": "δ-ferrite (+ austenite), simplified corner",
      "met2_ph_f": "Ferrite (α), the sliver below 0.022 % C",
      "met2_ph_fa": "Ferrite + austenite (α + γ)",
      "met2_ph_fp": "Ferrite + pearlite (α + P)",
      "met2_ph_liquid": "Liquid (L)",
